"""Apply Quantum Trader v3.5.43 (Angel manual-close sync, safe SELL retry,
MAZDOCK, option-board position chips). Refuses if any file differs from v3.5.42."""
import base64, hashlib, os, py_compile, sys, zlib
ITEMS = [{'f': 'backend/app/config.py', 'old': '200f7e12a4726c3e6865ca21355030c74baf5fb32ef42f08f148e09685bbc1f9', 'new': ''}, {'f': 'backend/app/main.py', 'old': '690df68cd3fc6fbfc4d1155f42124cac98780b2b44004762a8448faeae61ff3f', 'new': ''}, {'f': 'backend/app/market/instruments.py', 'old': '31a915891829ab0f5900dc5c7da422023ebf54d496326529a3320f5745c448bb', 'new': ''}, {'f': 'backend/app/state.py', 'old': 'dbb238c84c44c72abb71f61af29eb241a15dcdc1e74ceddd3157fcd591a142e8', 'new': ''}, {'f': 'frontend/components/QuantumSignal.tsx', 'old': '523b53de252aa7223fb428a54419dbd51afd3de3dbd105a0c23b51e2a4c17dca', 'new': ''}, {'f': 'frontend/lib/types.ts', 'old': '0d7895dfea747322b69d742cd2094b3367873b9fcaadddd7a0c2f7687fab7f7e', 'new': ''}, {'f': 'backend/_smoke_v3543.py', 'old': None, 'new': ''}]
bad = []
for it in ITEMS:
    p = it["f"]
    if it["old"] is None:
        continue
    if not os.path.exists(p):
        bad.append(p + " (missing)"); continue
    h = hashlib.sha256(open(p, "rb").read().replace(b"\r\n", b"\n")).hexdigest()
    new = zlib.decompress(base64.b64decode(it["new"]))
    if h == hashlib.sha256(new).hexdigest():
        print("already v3.5.43:", p); sys.exit(1)
    if h != it["old"]:
        bad.append(p)
if bad:
    print("REFUSED - these files are not the v3.5.42 version:", bad); sys.exit(1)
for it in ITEMS:
    p = it["f"]
    if it["old"] is not None:
        os.replace(p, p + ".pre3543.bak") if not os.path.exists(p + ".pre3543.bak") else None
    open(p, "wb").write(zlib.decompress(base64.b64decode(it["new"])))
    if p.endswith(".py"):
        py_compile.compile(p, doraise=True)
print("v3.5.43 applied OK (backups: *.pre3543.bak)")
